import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])

    if n == 0:
        print("Median: 0.0")
        return

    numbers = list(map(float, data[1:n+1]))
    numbers.sort()

    if n % 2 == 1:
        median = numbers[n // 2]
    else:
        mid1 = numbers[n // 2 - 1]
        mid2 = numbers[n // 2]
        median = (mid1 + mid2) / 2.0

    print(f"Median: {median}")

if __name__ == "__main__":
    main()
